// Process scene update request
const sceneData = $input.first().json;
const { 
  sceneId,
  action, // 'update', 'create', 'get', 'delete', 'transition'
  lightingChanges = {},
  weatherChanges = {},
  objectStateChanges = [],
  environmentalEffects = [],
  descriptionChanges = {},
  transitionTo = null
} = sceneData;

// Validate required fields
if (!sceneId || !action) {
  throw new Error('Missing required fields: sceneId, action');
}

// Prepare operation data
const operationData = {
  sceneId,
  action,
  timestamp: new Date().toISOString(),
  lightingChanges,
  weatherChanges,
  objectStateChanges,
  environmentalEffects,
  descriptionChanges,
  transitionTo,
  metadata: {
    processedBy: 'scene-management-workflow',
    version: '1.0'
  }
};

return { json: operationData };

// Generate dynamic scene description based on current state
const sceneData = $input.first().json;
const {
  sceneId,
  lightingChanges,
  weatherChanges,
  objectStateChanges,
  environmentalEffects,
  descriptionChanges
} = sceneData;

// Get current scene state
let currentScene = {
  sceneId,
  name: 'Unknown Location',
  baseDescription: 'A mysterious place.',
  lighting: 'normal',
  weather: 'clear',
  objects: [],
  environmentalEffects: [],
  timeOfDay: 'day',
  visibility: 'good',
  mood: 'neutral'
};

// Load existing scene data if available
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  const headerRow = $input[1].json.values[0];
  const dataRow = $input[1].json.values.find(row => row[0] === sceneId);

  if (dataRow) {
    currentScene = {
      sceneId: dataRow[0],
      name: dataRow[1] || 'Unknown Location',
      baseDescription: dataRow[2] || 'A mysterious place.',
      lighting: dataRow[3] || 'normal',
      weather: dataRow[4] || 'clear',
      objects: JSON.parse(dataRow[5] || '[]'),
      environmentalEffects: JSON.parse(dataRow[6] || '[]'),
      timeOfDay: dataRow[7] || 'day',
      visibility: dataRow[8] || 'good',
      mood: dataRow[9] || 'neutral',
      lastUpdated: dataRow[10] || new Date().toISOString()
    };
  }
}

// Apply changes
const newLighting = lightingChanges.type || currentScene.lighting;
const newWeather = weatherChanges.type || currentScene.weather;
let newObjects = [...currentScene.objects];
let newEnvironmentalEffects = [...currentScene.environmentalEffects];

// Update object states
objectStateChanges.forEach(change => {
  const { objectId, state, description } = change;
  const existingIndex = newObjects.findIndex(obj => obj.id === objectId);

  if (existingIndex >= 0) {
    newObjects[existingIndex] = {
      ...newObjects[existingIndex],
      state,
      description: description || newObjects[existingIndex].description
    };
  } else {
    newObjects.push({
      id: objectId,
      name: change.name || objectId,
      state,
      description: description || `An object in ${change.state} state.`,
      interactive: change.interactive !== false
    });
  }
});

// Update environmental effects
environmentalEffects.forEach(effect => {
  const { type, intensity, description } = effect;
  const existingIndex = newEnvironmentalEffects.findIndex(e => e.type === type);

  if (existingIndex >= 0) {
    newEnvironmentalEffects[existingIndex] = {
      ...newEnvironmentalEffects[existingIndex],
      intensity,
      description: description || newEnvironmentalEffects[existingIndex].description
    };
  } else {
    newEnvironmentalEffects.push({
      type,
      intensity,
      description: description || `${type} effect with ${intensity} intensity.`
    });
  }
});

// Generate dynamic description
function generateDynamicDescription(baseDesc, lighting, weather, objects, effects, timeOfDay) {
  let description = baseDesc;

  // Add lighting descriptions
  const lightingDesc = {
    'bright': 'The area is brightly illuminated, casting sharp shadows.',
    'normal': 'The lighting is moderate and clear.',
    'dim': 'The area is dimly lit, making details hard to discern.',
    'dark': 'Darkness pervades the area, requiring additional light to see clearly.',
    'magical': 'An otherworldly light illuminates the surroundings with an eerie glow.',
    'flickering': 'The light source flickers intermittently, creating an unsettling atmosphere.'
  };

  if (lightingDesc[lighting]) {
    description += ' ' + lightingDesc[lighting];
  }

  // Add weather descriptions
  const weatherDesc = {
    'clear': 'The weather is clear and calm.',
    'rain': 'Rain falls steadily, creating puddles and wet surfaces.',
    'storm': 'Thunder rumbles in the distance as lightning illuminates the sky.',
    'fog': 'A thick fog blankets the area, reducing visibility significantly.',
    'snow': 'Snow falls gently, covering everything in a white blanket.',
    'wind': 'Strong winds whip through the area, howling and whistling.',
    'mist': 'A light mist hangs in the air, creating a mysterious ambiance.'
  };

  if (weatherDesc[weather]) {
    description += ' ' + weatherDesc[weather];
  }

  // Add object descriptions for interactive/changed objects
  const interactiveObjects = objects.filter(obj => obj.interactive || obj.state !== 'normal');
  if (interactiveObjects.length > 0) {
    description += ' You notice:';
    interactiveObjects.forEach(obj => {
      description += ` ${obj.description}`;
    });
  }

  // Add environmental effect descriptions
  if (effects.length > 0) {
    description += ' ';
    effects.forEach(effect => {
      description += effect.description + ' ';
    });
  }

  // Add time of day context
  const timeDesc = {
    'dawn': 'As dawn breaks, the first rays of sunlight appear.',
    'morning': 'The morning sun casts long shadows.',
    'noon': 'The sun reaches its zenith, bathing everything in bright light.',
    'afternoon': 'Afternoon light creates a warm, golden glow.',
    'dusk': 'As dusk falls, colors deepen and shadows lengthen.',
    'evening': 'Evening descends, bringing a peaceful quiet.',
    'night': 'Night has fallen, and darkness envelops the landscape.'
  };

  if (timeDesc[timeOfDay]) {
    description += ' ' + timeDesc[timeOfDay];
  }

  return description.trim();
}

// Calculate visibility and mood based on conditions
let visibility = currentScene.visibility;
let mood = currentScene.mood;

if (newLighting === 'dark' || newWeather === 'fog') {
  visibility = 'poor';
} else if (newLighting === 'bright' && newWeather === 'clear') {
  visibility = 'excellent';
} else if (newLighting === 'dim' || newWeather === 'rain') {
  visibility = 'moderate';
}

if (newWeather === 'storm' || newLighting === 'flickering') {
  mood = 'tense';
} else if (newWeather === 'clear' && newLighting === 'bright') {
  mood = 'peaceful';
} else if (newLighting === 'magical') {
  mood = 'mysterious';
}

// Generate final description
const dynamicDescription = generateDynamicDescription(
  currentScene.baseDescription,
  newLighting,
  newWeather,
  newObjects,
  newEnvironmentalEffects,
  currentScene.timeOfDay
);

// Prepare updated scene data
const updatedScene = {
  sceneId,
  name: currentScene.name,
  baseDescription: currentScene.baseDescription,
  dynamicDescription,
  lighting: newLighting,
  weather: newWeather,
  objects: newObjects,
  environmentalEffects: newEnvironmentalEffects,
  timeOfDay: currentScene.timeOfDay,
  visibility,
  mood,
  lastUpdated: new Date().toISOString(),
  metadata: {
    lightingChanges,
    weatherChanges,
    objectStateChanges,
    environmentalEffects,
    processedBy: 'scene-dynamic-generator'
  }
};

return { json: updatedScene };

// Format scene data for Google Sheets
const sceneData = $input.first().json;

// Prepare row data in the correct order for Google Sheets
const rowData = [
  sceneData.sceneId,
  sceneData.name,
  sceneData.baseDescription,
  sceneData.lighting,
  sceneData.weather,
  JSON.stringify(sceneData.objects),
  JSON.stringify(sceneData.environmentalEffects),
  sceneData.timeOfDay,
  sceneData.visibility,
  sceneData.mood,
  sceneData.lastUpdated
];

return {
  json: {
    range: 'Scene_State!A:K',
    values: [rowData]
  }
};

// Send real-time scene update to WebSocket system
const sceneData = $input.first().json;
const { sceneId, metadata } = sceneData;

// Prepare WebSocket broadcast payload
const broadcastPayload = {
  type: 'scene_update',
  data: {
    sceneId,
    name: sceneData.name,
    description: sceneData.dynamicDescription,
    lighting: sceneData.lighting,
    weather: sceneData.weather,
    visibility: sceneData.visibility,
    mood: sceneData.mood,
    objects: sceneData.objects,
    environmentalEffects: sceneData.environmentalEffects,
    changes: {
      lighting: metadata.lightingChanges || {},
      weather: metadata.weatherChanges || {},
      objects: metadata.objectStateChanges || [],
      effects: metadata.environmentalEffects || []
    }
  },
  channels: [`scene_${sceneId}`, 'game_updates', 'dm_updates'],
  timestamp: new Date().toISOString()
};

// Send to WebSocket system
fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(broadcastPayload)
}).catch(error => {
  console.error('Failed to broadcast scene update:', error);
});

return { json: { broadcast: 'sent', sceneId } };

// Process scene transition request
const transitionData = $input.first().json;
const { 
  fromSceneId,
  toSceneId,
  transitionType = 'normal', // 'normal', 'combat', 'dramatic', 'subtle'
  duration = 5, // seconds
  transitionDescription = '',
  partyMembers = [],
  preserveState = true
} = transitionData;

// Validate required fields
if (!fromSceneId || !toSceneId) {
  throw new Error('Missing required fields: fromSceneId, toSceneId');
}

// Prepare transition data
const transitionOperation = {
  fromSceneId,
  toSceneId,
  transitionType,
  duration,
  transitionDescription,
  partyMembers,
  preserveState,
  timestamp: new Date().toISOString(),
  action: 'transition',
  metadata: {
    processedBy: 'scene-transition-workflow',
    version: '1.0'
  }
};

return { json: transitionOperation };

// Get destination scene data and prepare transition
const transitionData = $input.first().json;
const { fromSceneId, toSceneId, transitionType, duration } = transitionData;

// Get both scenes for transition
const scenes = {
  from: { sceneId: fromSceneId, name: 'Previous Scene' },
  to: { sceneId: toSceneId, name: 'Next Scene' }
};

// Generate transition narrative based on type
const transitionNarratives = {
  'normal': `The party moves from ${scenes.from.name} to ${scenes.to.name}.`,
  'combat': `As the battle concludes in ${scenes.from.name}, the party advances toward ${scenes.to.name}.`,
  'dramatic': `A dramatic transition unfolds as the party leaves ${scenes.from.name} and enters ${scenes.to.name}.`,
  'subtle': `Almost unnoticed, the party finds themselves moving from ${scenes.from.name} to ${scenes.to.name}.`,
  'magical': `With a flash of magical energy, the party is transported from ${scenes.from.name} to ${scenes.to.name}.`,
  'sudden': `Suddenly and without warning, the party finds themselves in ${scenes.to.name}, leaving ${scenes.from.name} behind.`
};

const transitionNarrative = transitionNarratives[transitionType] || transitionNarratives['normal'];

// Prepare transition data for broadcasting
const transitionBroadcast = {
  type: 'scene_transition',
  data: {
    fromScene: scenes.from,
    toScene: scenes.to,
    transitionType,
    duration,
    narrative: transitionNarrative,
    description: transitionData.transitionDescription || transitionNarrative,
    partyMembers: transitionData.partyMembers,
    preserveState: transitionData.preserveState
  },
  channels: ['game_updates', 'dm_updates', 'transitions'],
  timestamp: new Date().toISOString()
};

return { json: transitionBroadcast };

// Broadcast scene transition to all connected clients
const transitionData = $input.first().json;

// Send to WebSocket system
fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(transitionData)
}).catch(error => {
  console.error('Failed to broadcast scene transition:', error);
});

return { json: { 
  broadcast: 'sent', 
  transitionType: transitionData.data.transitionType,
  fromScene: transitionData.data.fromScene.sceneId,
  toScene: transitionData.data.toScene.sceneId
} };

