// Data validation for scene operations
const sceneData = $input.first().json;
const validationErrors = [];

// Validate scene ID format
if (!sceneData.sceneId || typeof sceneData.sceneId !== 'string') {
  validationErrors.push('Invalid scene ID format');
}

// Validate scene name
if (sceneData.name && typeof sceneData.name !== 'string') {
  validationErrors.push('Scene name must be a string');
}

// Validate lighting
if (sceneData.lighting) {
  const validLighting = ['bright', 'normal', 'dim', 'dark', 'magical', 'flickering'];
  if (!validLighting.includes(sceneData.lighting)) {
    validationErrors.push('Invalid lighting type');
  }
}

// Validate weather
if (sceneData.weather) {
  const validWeather = ['clear', 'rain', 'storm', 'fog', 'snow', 'wind', 'mist'];
  if (!validWeather.includes(sceneData.weather)) {
    validationErrors.push('Invalid weather type');
  }
}

// Validate visibility
if (sceneData.visibility) {
  const validVisibility = ['excellent', 'good', 'moderate', 'poor'];
  if (!validVisibility.includes(sceneData.visibility)) {
    validationErrors.push('Invalid visibility level');
  }
}

// Validate mood
if (sceneData.mood) {
  const validMoods = ['peaceful', 'neutral', 'tense', 'mysterious', 'dramatic', 'ominous'];
  if (!validMoods.includes(sceneData.mood)) {
    validationErrors.push('Invalid mood type');
  }
}

// Validate objects array
if (sceneData.objects && !Array.isArray(sceneData.objects)) {
  validationErrors.push('Objects must be an array');
}

// Validate environmental effects array
if (sceneData.environmentalEffects && !Array.isArray(sceneData.environmentalEffects)) {
  validationErrors.push('Environmental effects must be an array');
}

// Validate time of day
if (sceneData.timeOfDay) {
  const validTimes = ['dawn', 'morning', 'noon', 'afternoon', 'dusk', 'evening', 'night'];
  if (!validTimes.includes(sceneData.timeOfDay)) {
    validationErrors.push('Invalid time of day');
  }
}

// Return validation result
if (validationErrors.length > 0) {
  return {
    json: {
      valid: false,
      errors: validationErrors,
      sceneId: sceneData.sceneId
    }
  };
}

return {
  json: {
    valid: true,
    sceneData,
    sceneId: sceneData.sceneId
  }
};
